layer.css:
[data-ryt="pitch"] { color: rgb(80, 78, 73); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(80, 78, 73); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 0px; padding-bottom: 4px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgb(232, 230, 220); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px solid var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: rgb(107, 106, 100); font-family: "JetBrains Mono", "SF Mono", "Fira Code", Consolas, Monaco, "Source Han Serif SC", monospace; font-size: 11px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: 0.6px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(107, 106, 100); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.65; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s }
[data-ryt="header"] { border-bottom: 1px solid rgb(232, 230, 220); border-top: none }
[data-ryt="nav"] a { color: rgb(107, 106, 100); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: 1.2px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(107, 106, 100); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17px; font-weight: 500; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #2D5A8A; color: #1B365D }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #2D5A8A; color: #1B365D }
[data-ryt="nav"] a:hover { color: #2D5A8A; color: #1B365D }
[data-ryt="brand"]:hover { color: #2D5A8A; color: #1B365D }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #2D5A8A }
